/* ===== Inhalte: Kana-Tabellen und Grundkurs-Lektionen =====
   Grammatikpunkte je JLPT-Stufe: gram-n5.js … gram-n1.js. Lesetexte: texts-a.js … texts-c.js. Wort-Lexikon: lexicon.js. Wortschatz: core.js. */
/* Sammelbehälter für die Rohdaten der anderen Dateien (data.js bereitet sie auf) */
const GP_RAW = {}, GPX_RAW = {}, TEXT_RAW = {}, LEX_RAW = [];
/* Kana-Tabellen: je Zeile "Kana:Umschrift" durch Leerzeichen getrennt, - = leeres Feld. Katakana entstehen in der App aus den Hiragana. */
const KANA_RAW = {
  base: ['あ:a い:i う:u え:e お:o', 'か:ka き:ki く:ku け:ke こ:ko', 'さ:sa し:shi す:su せ:se そ:so', 'た:ta ち:chi つ:tsu て:te と:to', 'な:na に:ni ぬ:nu ね:ne の:no',
         'は:ha ひ:hi ふ:fu へ:he ほ:ho', 'ま:ma み:mi む:mu め:me も:mo', 'や:ya - ゆ:yu - よ:yo', 'ら:ra り:ri る:ru れ:re ろ:ro', 'わ:wa - - - を:o', 'ん:n - - - -'],
  dak:  ['が:ga ぎ:gi ぐ:gu げ:ge ご:go', 'ざ:za じ:ji ず:zu ぜ:ze ぞ:zo', 'だ:da ぢ:ji づ:zu で:de ど:do', 'ば:ba び:bi ぶ:bu べ:be ぼ:bo', 'ぱ:pa ぴ:pi ぷ:pu ぺ:pe ぽ:po'],
  yoon: ['きゃ:kya きゅ:kyu きょ:kyo', 'しゃ:sha しゅ:shu しょ:sho', 'ちゃ:cha ちゅ:chu ちょ:cho', 'にゃ:nya にゅ:nyu にょ:nyo', 'ひゃ:hya ひゅ:hyu ひょ:hyo', 'みゃ:mya みゅ:myu みょ:myo', 'りゃ:rya りゅ:ryu りょ:ryo',
         'ぎゃ:gya ぎゅ:gyu ぎょ:gyo', 'じゃ:ja じゅ:ju じょ:jo', 'びゃ:bya びゅ:byu びょ:byo', 'ぴゃ:pya ぴゅ:pyu ぴょ:pyo']
};
const KANA = {}; for (const k in KANA_RAW) KANA[k] = KANA_RAW[k].map(r => r.split(' ').map(c => c === '-' ? null : c.split(':')));
const toKatakana = s => s.replace(/[ぁ-ゖ]/g, c => String.fromCharCode(c.charCodeAt(0) + 96));

/* Grundkurs. o[0] ist immer die richtige Antwort (Reihenfolge wird beim Anzeigen gemischt).
   sec = weitere Abschnitte mit Überschrift (h), Absätzen (p) und Beispielen (ex); gp = Grammatikpunkte der Stufenlisten, die auf die Lektion verweisen. */
